易错提醒：想要整数结果必须写 //。很多人看到 2.0 以为出 bug，其实是 / 的固定行为。`,difficulty:1},{id:"s2-03-q2",qtype:"blank",stem:"要求出 17 除以 5 的余数，应该写成 17 ____ 5（只填运算符）。",answer:"%",accepted:["%","百分号","取余","mod"],explanation:`答案：%（百分号）。
